<script setup>
import {computed,ref,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';import ProductCard from '../components/ProductCard.vue';import {products} from '../data/products';
const route=useRoute(),router=useRouter(),query=ref(String(route.query.q||''));watch(()=>route.query.q,v=>query.value=String(v||''));const filtered=computed(()=>{const q=query.value.trim().toLowerCase();return q?products.filter(p=>[p.name,p.category,p.description].some(v=>v.toLowerCase().includes(q))):products});const search=()=>router.push({path:'/products',query:query.value.trim()?{q:query.value.trim()}: {}});const clear=()=>{query.value='';search();};
</script>
<template><section class="hero"><div><span>NIVORA COLLECTION / 08 OBJECTS</span><h1>Choose less. Keep longer.</h1></div><form @submit.prevent="search"><input v-model="query" name="q" placeholder="Search lighting, audio, workspace..."/><button>Search</button></form></section><section class="catalog"><div class="bar"><strong>{{filtered.length}} objects</strong><button v-if="query" @click="clear">Clear “{{query}}”</button></div><div v-if="filtered.length" class="grid"><ProductCard v-for="p in filtered" :key="p.id" :product="p"/></div><div v-else class="empty"><span>○</span><h2>No objects matched.</h2><button @click="clear">Reset search</button></div></section></template>
<style scoped>.hero{padding:76px 6vw 50px;display:grid;grid-template-columns:1fr 520px;gap:45px;align-items:end;background:var(--blue)}.hero span{font-size:10px;font-weight:900;letter-spacing:.18em}h1{margin:13px 0 0;font:400 clamp(56px,7vw,94px)/.92 Georgia;letter-spacing:-.05em}form{display:flex;gap:9px}input{flex:1;min-width:0;padding:15px 17px;border:1px solid rgba(31,35,31,.28);border-radius:999px;background:rgba(255,255,255,.55);font:inherit}form button,.empty button{padding:14px 20px;border:0;border-radius:999px;background:var(--ink);color:white;font-weight:800}.catalog{padding:42px 6vw 85px}.bar{margin-bottom:22px;display:flex;justify-content:space-between}.bar button{border:0;background:transparent;color:var(--coral-dark);font-weight:800}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}.empty{padding:90px;text-align:center;border:1px dashed var(--line);border-radius:28px}.empty span{font:400 100px Georgia}.empty h2{font:400 42px Georgia}@media(max-width:950px){.hero{grid-template-columns:1fr}.grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){.hero,.catalog{padding-inline:20px}.grid{grid-template-columns:1fr}form{display:grid}}</style>
